import json
def bands(g):
    rows=[r for r in range(len(g)) if any(g[r])]
    bs=[]; 
    for r in rows:
        if bs and r==bs[-1][-1]+1: bs[-1].append(r)
        else: bs.append([r])
    return bs
def try_fill(X,Y):  # X filled = X with 1 where X==0 and Y[c-1]!=0
    w=len(X[0]); out=[row[:] for row in X]; ok=True; nf=0
    for r in range(len(X)):
        for c in range(w):
            if X[r][c]==0 and c>0 and Y[r][c-1]!=0:
                out[r][c]=1; nf+=1
            elif X[r][c]!=0 and c>0 and Y[r][c-1]!=X[r][c]:
                ok=False
    return ok,out,nf
def transform(g):
    bs=bands(g)
    assert len(bs)==2, bs
    X=[g[r] for r in bs[0]]; Y=[g[r] for r in bs[1]]
    cands=[]
    for a,b in ((X,Y),(Y,X)):
        ok,out,nf=try_fill(a,b)
        if ok: cands.append((nf,out,bs[0] if a is X else bs[1]))
    assert len(cands)==1, len(cands)
    nf,out,rows=cands[0]
    res=[r[:] for r in g]
    for k,r in enumerate(rows): res[r]=out[k]
    return res
